package com.transportlogistics.app.fleet.payroll.adapters.outbound.persistence;
import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import java.util.*;
interface BatchJpaRepository extends JpaRepository<DriverPayrollBatchEntity,UUID>{Optional<DriverPayrollBatchEntity>findByTenantIdAndId(UUID t,UUID id);Optional<DriverPayrollBatchEntity>findByTenantIdAndIdempotencyKey(UUID t,String k);Optional<DriverPayrollBatchEntity>findByTenantIdAndExportEventId(UUID t,UUID eventId);List<DriverPayrollBatchEntity>findByTenantIdOrderByCreatedAtDesc(UUID t,org.springframework.data.domain.Pageable p);}
interface LineJpaRepository extends JpaRepository<DriverPayrollLineEntity,UUID>{List<DriverPayrollLineEntity>findByTenantIdAndBatchIdOrderById(UUID t,UUID b);boolean existsByTenantIdAndIdAndBatchId(UUID t,UUID id,UUID b);void deleteByTenantIdAndBatchId(UUID t,UUID b);@Query("select (count(l)>0) from DriverPayrollLineEntity l, DriverPayrollBatchEntity batch where l.tenantId=:t and l.driverId=:d and l.tripId=:trip and l.category=:c and l.batchId<>:b and l.originalLineId is null and batch.tenantId=l.tenantId and batch.id=l.batchId and batch.lifecycle in ('APPROVED','EXPORT_REQUESTED','EXPORTED')")boolean releasedRegularSourceExists(UUID t,UUID d,UUID trip,com.transportlogistics.app.fleet.payroll.domain.DriverPayrollInputLine.Category c,UUID b);@Query("select (count(l)>0) from DriverPayrollLineEntity l, DriverPayrollBatchEntity batch where l.tenantId=:t and l.driverId=:d and l.tripId=:trip and l.category=:c and l.batchId<>:b and l.originalLineId=:original and batch.tenantId=l.tenantId and batch.id=l.batchId and batch.lifecycle in ('APPROVED','EXPORT_REQUESTED','EXPORTED')")boolean releasedCorrectionSourceExists(UUID t,UUID d,UUID trip,com.transportlogistics.app.fleet.payroll.domain.DriverPayrollInputLine.Category c,UUID original,UUID b);}
interface WorkerMappingJpaRepository extends JpaRepository<DriverPayrollWorkerMappingEntity,UUID>{Optional<DriverPayrollWorkerMappingEntity>findByTenantIdAndDriverId(UUID t,UUID d);}
interface HistoryJpaRepository extends JpaRepository<DriverPayrollHistoryEntity,UUID>{List<DriverPayrollHistoryEntity>findByTenantIdAndBatchIdOrderByCreatedAtAsc(UUID t,UUID b);}
interface MappingCommandJpaRepository extends JpaRepository<DriverPayrollMappingCommandEntity,UUID>{Optional<DriverPayrollMappingCommandEntity>findByTenantIdAndIdempotencyKey(UUID t,String key);@Query(value="select pg_advisory_xact_lock(hashtext(cast(:tenantId as text)),hashtext(:idempotencyKey))",nativeQuery=true)void lock(UUID tenantId,String idempotencyKey);}
